// ═══════════════════════════════════════════════════════════════════════
// ESLint config — flat config (ESLint 9.x)
// ═══════════════════════════════════════════════════════════════════════
// Scope: every .js and .jsx under app/src/main/assets/src (every source
// module; count them with ls/wc, a number here drifts), plus
// service-worker.js and tools/ (base rules only). Out of scope: dist (built output), .min.js (vendor),
// src/data (auto-generated corpus data, would be pure noise).
//
// NB: line comments throughout this header — block /* */ comments break
// when they contain JS-glob syntax like `src/**/*.js` because the `*/`
// inside the glob prematurely closes the block. Lesson learned.

// The projectGlobals object is AUTO-GENERATED by tools/gen-eslint-globals.py
// from the bundle entry files + index.html + corpus. Regenerate via:
//     npm run lint:globals
// `npm run lint` chains lint:globals first, and the pre-commit hook also
// regens — so the globals list cannot go stale relative to the bundles.
//
// Plugins:
//   - @eslint/js                — recommended base rules
//   - eslint-plugin-react       — JSX-aware (key warnings, jsx-uses-react,
//                                 jsx-no-undef, etc.). Applicable as of
//                                 Q2.7-2 — the entire UI surface is JSX.
//   - eslint-plugin-react-hooks — rules-of-hooks + exhaustive-deps.
//                                 Exhaustive-deps is the highest-value
//                                 bug-catcher here: would have caught the
//                                 journalEntryId stale-closure fixed in
//                                 P6l. NEVER auto-fixed (see Q3.3 plan).
//
// Rule philosophy:
//   - Base + react + react-hooks recommended sets.
//   - NO style rules (semi, indent, quotes). Style is Prettier's job —
//     a later phase, not this one.
//   - no-unused-vars warns, doesn't error (lots of _var placeholders
//     that the linter shouldn't reject outright).
// ═══════════════════════════════════════════════════════════════════════

import js from '@eslint/js';
import reactPlugin from 'eslint-plugin-react';
import reactHooksPlugin from 'eslint-plugin-react-hooks';
import globals from 'globals';

import { projectGlobals } from './tools/eslint-globals.generated.js';

/* hooks-2 selector (the comment at its use in the src block says what and why). A const because the src test-file
   block below sets no-restricted-syntax again, and a later block replaces the options, so it lists this one too. */
const SUBSCRIBE_SYNTAX = (() => {
  const steps = [
    ['ConditionalExpression', 'consequent'], ['ConditionalExpression', 'alternate'],
    ['LogicalExpression', 'left'], ['LogicalExpression', 'right'],
    ['SequenceExpression', 'expressions.1'], ['SequenceExpression', 'expressions.2'],
    ['AssignmentExpression', 'right'],
  ];
  /** @type {Array<Array<[string, string]>>} */
  const paths = [[]];
  for (let depth = 0; depth < 3; depth++) {
    for (const p of paths.filter((q) => q.length === depth)) for (const s of steps) paths.push([...p, /** @type {[string, string]} */ (s)]);
  }
  const alts = [];
  for (const p of paths) {
    let at = 'arguments.0';
    let guard = '';
    for (const [type, key] of p) { guard += `[${at}.type='${type}']`; at += '.' + key; }
    alts.push(`${guard}[${at}.type='MemberExpression']`, `${guard}[${at}.type='ChainExpression'][${at}.expression.type='MemberExpression']`);
  }
  return {
    selector: "CallExpression:matches([callee.property.name='useSyncExternalStore'], [callee.name='useSyncExternalStore']):matches(" + alts.join(', ') + ')',
    message: 'Pass the subscribe wrapped, not as X.subscribe (or s?.subscribe, or one behind a ternary, && || ??, a comma or an assignment): a store whose subscribe uses `this` would subscribe nothing. Use useStoreVersion(X) (hooks/use-store-version.js; inert for a null store) or React.useCallback((cb) => X.subscribe(cb), []). Not caught: an alias, a destructure or a renamed import of subscribe; getSnapshot is not checked.',
  };
})();

/* sleep-test (2026-11-26). The pre-commit hook's fast run (VOT_VITEST_FAST=1, vitest.config.js) runs tests in the
   vmThreads pool, where the global object is jsdom's window itself. Its document, window, location and top are
   unforgeable (non-configurable), so vi.stubGlobal on one throws "Cannot redefine property", while the default pool
   (CI, the hook's fallback) passes: a test red on the first run and green on the second. Measured in both pools
   2026-11-26: self and navigator stub fine, so they are not refused. Fake one property of the real object instead,
   as utils/audio-player/sleep.test.js and utils/song-catalog.test.js do. Not caught: a name held in a variable. */
const STUB_GLOBAL_SYNTAX = {
  selector: "CallExpression[callee.object.name='vi'][callee.property.name='stubGlobal']" +
    ':matches([arguments.0.value=/^(document|window|location|top)$/], ' +
    '[arguments.0.type=TemplateLiteral][arguments.0.quasis.0.value.cooked=/^(document|window|location|top)$/])',
  message: "vi.stubGlobal can't replace document, window, location or top: in the vmThreads pool (the pre-commit hook's fast run, VOT_VITEST_FAST=1) they are jsdom's unforgeable properties and it throws \"Cannot redefine property\". Fake the one property you need on the real object instead: Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => v }), and put the saved descriptor back (or Reflect.deleteProperty) in afterEach. See utils/audio-player/sleep.test.js.",
};

export default [
  // Global ignores — applies before any other config matches.
  {
    ignores: [
      'app/src/main/assets/dist/**',
      'app/src/main/assets/*.min.js',
      'app/src/main/assets/search-data.js',
      'app/src/main/assets/src/data/**',
      'app/src/main/assets/src/search/vendor/**',
      'node_modules/**',
      'tools/eslint-globals.generated.js',
    ],
  },

  // Base + React + React Hooks for all src/ files.
  {
    files: ['app/src/main/assets/src/**/*.{js,jsx}'],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'module',
      parserOptions: {
        ecmaFeatures: { jsx: true },
      },
      globals: {
        ...globals.browser,
        ...projectGlobals,
        // Override: __scrollEl is module-mutable (declared `let` in inline #3
        // at index.html, written by ScreenLayout's ref callback). The
        // generator defaults all globals to readonly; this is the one
        // exception. If more module-mutable globals surface, list them here.
        __scrollEl: 'writable',
      },
    },
    plugins: {
      react: reactPlugin,
      'react-hooks': reactHooksPlugin,
    },
    settings: {
      react: { version: '18.2' },
    },
    rules: {
      // Base recommended
      ...js.configs.recommended.rules,
      // React recommended
      ...reactPlugin.configs.recommended.rules,
      // React Hooks recommended (rules-of-hooks + exhaustive-deps)
      ...reactHooksPlugin.configs.recommended.rules,
      // Local tweaks
      // caughtErrorsIgnorePattern: '^_' makes `catch (_e)` exempt from
      // no-unused-vars's caughtErrors check (which defaults to 'all' in
      // ESLint 9). Matches the existing argsIgnorePattern / varsIgnorePattern
      // convention so all three unused-var classes share one prefix policy.
      'no-unused-vars': ['warn', { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' }],
      'react/prop-types': 'off',   // JSDoc types will cover this (Q4 phase)
      'react/display-name': 'off', // anonymous components are fine in this codebase
      // jsx-no-undef's default is to ignore languageOptions.globals (legacy
      // eslintrc behavior). allowGlobals: true makes it respect the globals
      // list, which is the whole point of having a 322-entry generated list.
      'react/jsx-no-undef': ['error', { allowGlobals: true }],
      // no-empty: downgraded to warn (Q3.3b). Every empty catch in the
      // codebase intentionally swallows a non-fatal failure (localStorage
      // quota, IDB unsupported, native bridge missing, helper malformed-data).
      // Each site has a one-line inline reason comment naming the category.
      // The rule stays as warn so future empty-catch additions without a
      // reason still surface for review. See Q3 exit criteria — no-empty
      // warnings are an accepted category alongside exhaustive-deps and
      // no-unused-vars.
      'no-empty': 'warn',

      /* webkit-compat-1. `requestIdleCallback` has never shipped in WebKit —
         no Safari, and no iOS browser of any brand, since every iOS engine is
         WebKit. A bare reference is a ReferenceError on those devices, not a
         graceful degradation. Every call site here did carry the guard, and
         the most recent one carried it by hand again, which is the shape that
         eventually forgets. utils/on-idle.js is the guard, once; this rule is
         what stops the bare global coming back past review. */
      'no-restricted-globals': ['error',
        { name: 'requestIdleCallback', message: 'WebKit has never shipped it. Use onIdle() from utils/on-idle.js — it carries the guard, the timeout and the matching cancel.' },
        { name: 'cancelIdleCallback', message: 'Use the cancel function onIdle() returns; it knows which API it scheduled with.' },
      ],

      /* hooks-2 (audit 2026-11-23). React.useSyncExternalStore(X.subscribe, ...) hands React the bare function:
         a store whose subscribe uses `this` then subscribes nothing (in the sloppy-mode bundles `this` is window)
         and the screen silently stops updating. Pass useStoreVersion(X) from hooks/use-store-version.js, or a
         wrapper: React.useCallback((cb) => X.subscribe(cb), []).
         The subscribe argument is refused when it can evaluate to a bare member: X.subscribe or s?.subscribe,
         reached directly or through up to three expressions that hand back one of their parts unchanged (either
         branch of a ternary, either side of && || ??, the last of a comma list, the right of an assignment), so
         `s ? s.subscribe : noop`, `S.subscribe || noop`, `s?.subscribe ?? noop`, `(0, S.subscribe)`.
         One :matches, so a call reports once. Known gaps, by design of a syntax rule: an alias
         (const sub = s.subscribe), a destructure (const { subscribe } = s) and a renamed import reach React as
         a plain identifier and pass. getSnapshot is not checked: 9 sites pass a bare one (X.getVersion and the like)
         that the review of 2026-11-26 found safe, and refusing the shape would trip them. */
      'no-restricted-syntax': ['error', SUBSCRIBE_SYNTAX],

      // ─── React Compiler rule shed (Q3.3a-compiler-disable) ────────────────
      // eslint-plugin-react-hooks@7's recommended set ships 16 rules. Two of
      // them (rules-of-hooks, exhaustive-deps) are the canonical pair every
      // React app needs. The other 14 are React Compiler analysis rules —
      // they enforce invariants the optimizing compiler relies on. This
      // codebase is React 18.2 with no Compiler in use or planned, so those
      // 14 rules are forward-looking constraints that don't catch any
      // runtime bug today. Disabling them wholesale eliminates 54 baseline
      // errors with zero behavioral impact.
      //
      // set-state-in-render: real-bug class (infinite render loop) and worth
      // keeping defensively — BUT current baseline shows 0 hits, so disabling
      // it now matches the "shed everything Compiler-era while clean" policy.
      // If a real call-setter-in-render bug appears later, exhaustive-deps +
      // a careful review during Q4 (types) will catch the worst variants.
      // ──────────────────────────────────────────────────────────────────────
      'react-hooks/static-components': 'off',
      'react-hooks/use-memo': 'off',
      'react-hooks/preserve-manual-memoization': 'off',
      'react-hooks/incompatible-library': 'off',
      'react-hooks/immutability': 'off',
      'react-hooks/globals': 'off',
      'react-hooks/refs': 'off',
      'react-hooks/set-state-in-effect': 'off',
      'react-hooks/error-boundaries': 'off',
      'react-hooks/purity': 'off',
      'react-hooks/set-state-in-render': 'off',
      'react-hooks/unsupported-syntax': 'off',
      'react-hooks/config': 'off',
      'react-hooks/gating': 'off',
    },
  },

  // The service worker: a classic script in the worker scope, outside the
  // bundles, so it gets the worker globals and the base rules only.
  {
    files: ['app/src/main/assets/service-worker.js'],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'script',
      globals: { ...globals.serviceworker },
    },
    rules: {
      ...js.configs.recommended.rules,
      'no-unused-vars': ['warn', { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' }],
      'no-empty': 'warn',
    },
  },

  // tools/: Node scripts and their tests. The e2e and smoke drivers pass
  // callbacks to page.evaluate(), which run in the page, so the browser
  // globals and the app's own bare names are in scope there too.
  {
    files: ['tools/**/*.{js,mjs}'],
    languageOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
      globals: { ...globals.node, ...globals.browser, ...projectGlobals },
    },
    rules: {
      ...js.configs.recommended.rules,
      'no-unused-vars': ['warn', { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' }],
      'no-empty': 'warn',
    },
  },

  // Test files: no vi.stubGlobal on jsdom's unforgeable globals (STUB_GLOBAL_SYNTAX above). The src block's hooks-2
  // selector is listed again because this block's no-restricted-syntax replaces that block's options.
  {
    files: ['app/src/main/assets/src/**/*.test.{js,jsx}'],
    rules: { 'no-restricted-syntax': ['error', SUBSCRIBE_SYNTAX, STUB_GLOBAL_SYNTAX] },
  },
  {
    files: ['tools/**/*.test.{js,mjs}'],
    rules: { 'no-restricted-syntax': ['error', STUB_GLOBAL_SYNTAX] },
  },
];
